update content_bodies set title = 'Yamada Anna | Walking in the Mysterious Island - Amami Oshima, Tatsugo Town - 60 Seconds Version [Tabiiro Movie]', description = 'In July 2021, Amami Oshima was registered as a UNESCO World Natural Heritage site. Among its attractions, Tatsugo Town is a nature-rich area surrounded by calm seas and mountains. Join Yamada Anna on her first visit to Amami Oshima as she explores the natural beauty and enjoys the local flavors of the island.' where id = 'oOHsRcErnfvBeQeFtFxMo';
update content_bodies set title = '岡山を観光する際に訪れたい温泉地', description = 'この動画は岡山県を訪れる旅行者のためのガイドで、岡山の温泉地に焦点を当てています。湯郷温泉、奥津温泉、湯原温泉、上齋原温泉、作州武蔵温泉、たまの温泉など、いくつかのおすすめの温泉が紹介されています。視聴者は、コメント欄で他のおすすめを共有するよう促されています。『旅行の達人』というチャンネルは、旅行をより楽しく快適にするための情報を提供し、旅行が人生を豊かにするという考えを広めることを目指しています。最新情報や旅行のヒントを得るために、チャンネル登録やSNSのフォローを推奨しています。' where id = 'EazSwTbHeIGQhhRMxtbTw';
update content_bodies set title = 'Recommended Hot Springs to Visit in Okayama', description = 'This video serves as a guide for travelers planning to visit Okayama Prefecture, focusing on its hot spring destinations. It highlights several recommended hot springs, including Yugo Onsen, Okutsu Onsen, Yubara Onsen, Kamisaibara Onsen, Sakushu Musashi Onsen, and Tamano Onsen. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to provide comprehensive travel information to enhance the enjoyment and comfort of trips, promoting the idea that travel enriches life. For more updates and travel tips, viewers can subscribe to the channel and follow its social media accounts.' where id = 'lI4gEoaGVIjxgw5WSwcct';
update content_bodies set title = '長谷川京子｜神話の里・高千穂でパワーチャージ【旅色Movie】', description = '長谷川京子さんが、古事記や日本書紀に登場する神話の舞台が多く存在する宮崎県の高千穂を旅する特別なムービーです。神々の気配を感じられる豊かな自然の中で、1泊2日の旅を通じて高千穂を巡ります。見るだけで癒されるような旅の映像が楽しめます。' where id = 'B_5kFCWm4Ks6GxR6wg7Kj';
update content_bodies set title = 'Kyoko Hasegawa | Power Charge in Takachiho, the Land of Myths [Tabiiro Movie]', description = 'In this special movie, Kyoko Hasegawa travels to Takachiho in Miyazaki Prefecture, a place rich in mythology featured in ancient texts like the ''Nihon Shoki'' and ''Kojiki.'' Over a two-day trip, she explores the abundant natural beauty of the area, where one can feel the presence of the gods. This travel movie offers a healing experience just by watching.' where id = 'UcCWum5SSzGtHJFSO7zi_';
update content_bodies set title = '高野口小学校', description = '和歌山県に位置する高野口小学校についての情報が提供されています。また、和歌山県インターネット放送局のリンクも含まれており、地域の情報やイベントをオンラインで視聴することができます。' where id = '7Zgq7VVyi0IF0hXTIFVZ9';
