update content_bodies set title = '【福岡観光】九州地方の中心都市福岡で王道＆定番の観光スポットを楽しみたい', description = '福岡県への旅行や観光の参考として、王道＆定番の観光スポットを紹介する動画です。動画に紹介されていないオススメがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者に新しい可能性を発見してもらいたいと考えています。動画では、太宰府天満宮、門司港レトロ、福岡タワー、糸島、能古島、中洲の屋台などの観光スポットが紹介されています。詳細は公式サイトやSNSで確認してください。' where id = 'WOIs25NVlHZ9eV3T7ptkz';
update content_bodies set title = 'Fukuoka Tourism: Enjoy Classic and Must-See Attractions in Fukuoka, the Heart of Kyushu', description = 'This video serves as a guide for those traveling to Fukuoka Prefecture, showcasing classic and must-see tourist spots. If you have any recommendations not mentioned in the video, please share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team believes in enriching lives through travel and encourages viewers to explore new possibilities. The video highlights several attractions, including Dazaifu Tenmangu, Mojiko Retro, Fukuoka Tower, Itoshima, Nokonoshima, and Nakasu Yatai. For more information, please check the official website or social media links provided.' where id = 'jvoSHghceLTe0xAr_lKbF';
update content_bodies set title = '東京で贅沢気分に浸れるランチグルメ', description = 'この動画は、東京都を訪れる旅行者や観光客のためのガイドとして、贅沢な気分を味わえるランチスポットを紹介しています。動画で紹介されていないおすすめの場所があれば、ぜひコメント欄でシェアしてほしいとのことです。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しく快適にすることを目的としています。運営チームは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。' where id = 'MtWHHxhr79AW4hi7jTlr8';
