update content_bodies set title = '日本の境港市のツアー', description = 'このウェブマガジン「旅色」は、鳥取県にある境港市の特集を紹介しています。特別なムービーが2本あり、1本は180秒、もう1本は60秒の長さです。詳細については「旅色」の公式HPを訪れることができます。' where id = '97-NaHXF_UIwQkdJGLF65';
update content_bodies set title = 'A tour of Sakaiminato city in Japan', description = 'This web magazine feature highlights Sakaiminato city, located in Tottori prefecture, Japan. It includes links to special movies showcasing the city, with one being 180 seconds long and another 60 seconds long. For more information, you can visit the official website of ''Tabiiro''.' where id = '6Fql2qwCu09c4CtrFgROc';
update content_bodies set title = '日本の境港市のツアー', description = 'この記事では、鳥取県に位置する境港市を特集したウェブマガジン「旅色 FO-CAL」を紹介しています。境港市の魅力や文化的な重要性を強調し、観光名所を紹介しています。また、境港のビジュアルツアーを提供する特別なムービーも用意されています。詳細については「旅色」の公式ウェブサイトを訪れることができます。' where id = 'rU3fj2pQfx9nHA-fAcJ2N';
update content_bodies set title = 'A tour of Sakaiminato city in Japan', description = 'This article features Sakaiminato city located in Tottori prefecture, Japan, as part of the web magazine ''Tabiiro FO-CAL.'' It highlights the unique aspects of the city, showcasing its attractions and cultural significance. A special movie is also available, providing a visual tour of Sakaiminato. For more information, you can visit the official website of ''Tabiiro.''' where id = 'sJFYIjPGE6rblg_fdOPti';
update content_bodies set title = '高橋メアリージュン｜松江市（鳥取県）を巡る旅 60秒Ver【旅色Movie】', description = '松江は宍道湖や中海に囲まれた水の都で、江戸初期の城郭が残る城下町です。藩主にゆかりのあるお茶や和菓子文化、伝説の占いの池、美肌の温泉など、自然と歴史が豊かに融合したこの地で、訪れる人々はご褒美のような時間を過ごすことができます。松江観光協会や市の公式サイトも紹介されており、観光情報が充実しています。' where id = 'Diq3_zJJFwwzWB96PsEgA';
update content_bodies set title = 'Maryjun Takahashi | A Journey Through Matsue City (Tottori Prefecture) 60-Second Version [Tabiiro Movie]', description = 'Matsue, a castle town from the early Edo period, is surrounded by the waters of Lake Shinji and Nakatsu. This city offers a rich experience of nature and history, featuring tea and wagashi culture linked to the feudal lords, a legendary fortune-telling pond, and beautiful skin hot springs. It is a journey that allows visitors to enjoy a rewarding time in this water city.' where id = 'PR1-sZFvpXhxwSwGwc_Lp';
