update content_bodies set title = '【滋賀旅行】滋賀県の穴場スポット10選 #shorts', description = '滋賀県への旅行や観光に役立つ情報を提供します。今回は、地元の人々にも人気のある穴場スポットを10カ所紹介します。この動画で紹介されていないおすすめの場所があれば、ぜひコメント欄で教えてください。' where id = '8JLr5VhF9p9ggGdPB1pvu';
