update content_bodies set title = '中村ゆり｜フルーツの生産量が日本トップクラス　和歌山県湯浅のおいしい旅', description = '湯浅町は醤油の発祥地として知られ、海の幸も豊富で、グルメを楽しむには最適な場所です。この旅ムービーでは、中村ゆりさんと共に湯浅町を散策し、観光名所や絶景スポットを紹介します。旅のプランには、「湯浅美味いもん蔵」でのランチ、「湯浅ワイナリー」での大人の飲み物探し、「角長　職人蔵＆醤油資料館」での醤油の歴史や作り方の学び、「レストランドリーム」での釣りたての魚を使ったランチ、そして「花莚」でのスイーツを楽しむ内容が含まれています。' where id = 'DPXDSICwkdn-r2HjJSU1I';
update content_bodies set title = 'Yuri Nakamura | A Delicious Journey in Yuasa, Wakayama, Known for Its Top-Class Fruit Production', description = 'Yuasa Town, famous as the birthplace of soy sauce, is abundant in seafood, making it an ideal destination for gourmet travel. This travel movie features a journey through Yuasa Town with Yuri Nakamura, exploring various attractions and breathtaking spots. The itinerary includes lunch at ''Yuasa Oishaimon Kura,'' a visit to ''Yuasa Winery'' for adult beverages, learning about the history and production of soy sauce at ''Kakunaga Shokunin Kura & Soy Sauce Museum,'' enjoying lunch with freshly caught fish at ''Restaurant Dream,'' and indulging in desserts at ''Hanakan.''' where id = 'mKE2VKfAL7RHYg-9aZWc_';
update content_bodies set title = 'ラーメン激戦区の埼玉で美味しいラーメングルメを食べ尽くそう', description = '埼玉県への旅行や観光の参考として、埼玉県の美味しいラーメングルメを紹介する動画です。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。また、旅行の達人の公式LINEアカウントでは、賢くお得に旅行する方法を随時配信しています。このチャンネルは、観光、移動、宿泊、食事など、旅行をより楽しく快適にする情報を提供することを目的としています。旅行を通じて人生を豊かにすることを目指し、視聴者が新しい可能性を発見できるようサポートしています。' where id = 'gXk9SndpRdHVef96TByuM';
