update content_bodies set title = '心に響く四季がある鳥羽', description = '鳥羽の春夏秋冬を「心に響く四季がある」というテーマで感情的に表現した作品です。春は始まりを、夏は思い出を、秋は豊かさを、冬は温もりを象徴しています。' where id = 'c7Bmwy1o38erZBCCwi5s7';
