update content_bodies set title = '木村多江｜いま、文化に触れて感じたい 京都へ【旅色Movie】', description = '京都府には歴史的建造物や自然に囲まれた伊根町、独自の街並みを持つ与謝野町など、知られざる魅力が存在します。木村多江さんは「文化の幅広さを知りました」と語り、今回の旅を振り返ります。旅の内容は、京都府庁旧本館の訪問、ちりめん街道と呼ばれる独特の街並み、与謝野町唯一のカフェ「2Rin」での温かい体験、染色体験、舟屋のまちでのゆったりとした時間、江戸時代から続く向井酒造の見学、旬の味を楽しむ「鮨割烹海宮」、舞鶴湾の海辺にある舞鶴赤れんがパークでの締めくくりなど、多彩な内容が盛り込まれています。' where id = '-gknNP5qcc7aebo7oBjjZ';
update content_bodies set title = 'Tae Kimura | Experiencing Culture in Kyoto【Tabiiro Movie】', description = 'Kyoto Prefecture is home to historical buildings, the nature-surrounded town of Ine, and the unique streets of Yosano, showcasing its hidden charms. Tae Kimura reflects on her journey, stating, ''I learned about the breadth of culture.'' The trip includes visits to the former Kyoto Prefectural Office, the unique streets known as ''Chirimen Kaido,'' the only café in Yosano called ''2Rin,'' a dyeing experience, leisurely time in a fishing village, a visit to Mukai Sake Brewery, and enjoying seasonal flavors at ''Sushi Kappo Umikyu,'' concluding at the Maizuru Red Brick Park by Maizuru Bay.' where id = 'YDMgMvVLnNGhauVHqXHkW';
update content_bodies set title = '兵庫観光：買い物とグルメが楽しめる神戸ハーバーランド', description = 'この動画では、兵庫県にある大型複合施設・神戸ハーバーランドを紹介しています。旅行や観光の参考にしていただければと思います。また、動画で紹介されていないおすすめスポットがあれば、コメント欄でシェアしてほしいとのことです。チャンネル「旅行の達人」は、観光、移動、宿泊、食事などの情報を提供し、旅行を通じて人生を豊かにすることを目指しています。公式SNSアカウントをフォローし、チャンネル登録をすることで、さらに多くの情報を得ることができます。' where id = 'pJ1kC_IbKMoUCru9uL02I';
