update content_bodies set title = 'Tottori Tourism: 10 Must-Visit Spots When You Go to Tottori Sand Dunes!', description = 'This video serves as a guide for those traveling to Tottori Prefecture, highlighting the Tottori Sand Dunes. If you have any recommendations not mentioned in the video, please share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more information and updates, follow their official social media accounts.' where id = 'H8NKRk0Vc1NDrin88TtCd';
