update content_bodies set title = 'Kochi Travel: A 1-Night, 2-Day Gourmet Trip for Couples by Rental Car', description = 'This video serves as a guide for couples traveling to Kochi Prefecture. It highlights a rental car trip, showcasing various gourmet spots to visit. Viewers are encouraged to share their own recommendations in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, with a team that spends nearly half the year traveling. The video includes specific locations such as Hirome Market, Katsuo no Tataki, and various local dishes. Viewers are advised to check official websites for the latest information before visiting.' where id = 'v1f3qi3j1g_HI4E8KmFBj';
