update content_bodies set title = '内田理央｜私を元気にする山形の旅【旅色Movie】', description = '山形県はエリアごとに多彩な魅力が詰まっています。山形駅を起点に、山形タウン、銀山温泉、最上川、酒田を北上することで、フルーツやそば、温泉、歴史ある街並みなどに出会い、豊かな時間を過ごすことができます。案内役の内田理央さんは「おいしいものとレトロな町が大好き！」と語り、新しい発見の連続でワクワクが止まらない1泊2日の旅を楽しみました。' where id = '0mVBLOLJvZmTkf3YdZ4HH';
update content_bodies set title = 'Riao Uchida | A Journey in Yamagata that Energizes Me【Tabi-iro Movie】', description = 'Yamagata Prefecture is filled with diverse attractions in each area. Starting from Yamagata Station, one can explore Yamagata Town, Ginzan Onsen, Mogami River, and Sakata, discovering fruits, soba noodles, hot springs, and historical streets, all while enjoying a rich experience. The guide for this journey is Riao Uchida, who expresses her love for delicious food and retro towns. She enjoyed an exciting two-day trip filled with continuous new discoveries.' where id = 'zFJG5mGSIZaVrmRti7ym6';
update content_bodies set title = 'まったり奈良旅行のおすすめスポット', description = 'この動画は、奈良県への旅行を計画している方に向けて、ひとり旅におすすめのスポットを紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』というチャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。最新情報や更新については、公式のSNSアカウントをフォローしてください。' where id = 'YDgvsvZ1cdn7znqwQ1qUS';
update content_bodies set title = 'Recommended Spots for a Relaxing Solo Trip in Nara', description = 'This video serves as a guide for those planning to travel to Nara Prefecture, highlighting recommended spots for solo travelers. If you have any additional recommendations not mentioned in the video, please feel free to share them in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more information and updates, you can follow their official social media accounts.' where id = 'sDaRnFzqDSumBJ0gBnGoj';
update content_bodies set title = '四季の移ろい : 秋', description = '鳥羽の春夏秋冬を「心に響く四季がある」というタイトルで感情的に表現した作品です。春は始まりを、夏は思い出を、秋は豊かさを、冬は温もりを象徴しています。四季それぞれが持つ感情を通じて、鳥羽の自然の美しさとその変化を感じることができます。' where id = '36_5_lrlOrVEgDRnpXbvj';
update content_bodies set title = 'with the turning seasons : Autumn', description = 'The work expresses the four seasons of Toba through emotional representations, encapsulated in the phrase ''four seasons that resonate in the heart.'' Each season is associated with a specific emotion: Spring symbolizes new beginnings, Summer evokes memories, Autumn represents richness, and Winter conveys warmth.' where id = '0ElkP4fsSPGgpHBMwDPjQ';
update content_bodies set title = '島根観光/ひとり旅のおすすめスポット６選', description = 'この動画では、島根県への旅行を計画している方に向けて、ひとり旅におすすめのスポットを紹介しています。視聴者には、他のおすすめスポットがあればコメント欄でシェアしてほしいと呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行をより楽しくするための情報を提供することを目的としています。旅行を通じて人生を豊かにし、新しい可能性を発見することを促しています。動画では、出雲大社や足立美術館など、特定の６つのスポットが紹介されています。訪問前には公式サイトで最新情報を確認することが推奨されています。' where id = 'AAZ4Md72DR85N2k7wD2I3';
update content_bodies set title = 'Recommended Spots for Solo Travel in Shimane', description = 'This video provides recommendations for solo travel spots in Shimane Prefecture, Japan. It aims to serve as a guide for those planning a trip to Shimane. Viewers are encouraged to share any additional recommendations in the comments section. The channel, ''Travel Master,'' focuses on delivering various travel information, including sightseeing, transportation, accommodation, and dining, to enhance the travel experience. The mission is to enrich lives through travel, encouraging people to explore new possibilities and enjoy unique experiences. The video highlights six specific locations, including Izumo Taisha Shrine and the Adachi Museum of Art, among others. Viewers are advised to check official websites for the latest information before visiting.' where id = 'wZ2uQ2Yrheq7Zr4-hAMQF';
update content_bodies set title = 'コスパもよくておいしい！大阪難波のデカ盛りグルメ６選', description = 'この動画では、大阪難波のデカ盛りグルメを6つ紹介しています。旅行や観光の参考にしてください。動画に紹介されていないおすすめがあれば、コメント欄でシェアしてください。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行を通じて人生を豊かにすることを目指しています。新しい可能性を発見するために、ぜひ旅行に出かけてみてください。公式SNSアカウントもフォローして、最新情報をチェックしましょう。' where id = 'LAuvCBobfxWBcq286Cq4A';
update content_bodies set title = 'Delicious and Cost-Effective! 6 Large Portion Gourmet Spots in Namba, Osaka', description = 'This video introduces six large portion gourmet spots in Namba, Osaka, perfect for travelers and tourists. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team believes in enriching lives through travel and encourages viewers to explore new possibilities. For more travel tips and updates, you can follow their official social media accounts.' where id = 'nA38u7aZiZrUvLNPBU7jT';
update content_bodies set title = '奈緒｜おいしい十勝アドレス【旅色Movie】', description = '北海道・十勝エリアは、日本有数の農業・酪農地帯として知られ、19市町村で構成されるこの地域の食料自給率は約1,100％に達します。食材の宝庫であるため、旅では絶品グルメとの出会いが続きます。おいしいものに目がない奈緒さんが十勝の町を巡り、大地の恵みを満喫しました。奈緒さんは1995年2月10日生まれ、福岡県出身で、NHK連続テレビ小説『半分、青い。』でヒロインの親友役として注目を集めました。その後、『あなたの番です』や映画『余命10年』『マイ・ブロークン・マリコ』などに出演し、2023年にはエランドール賞新人賞と第116回ザテレビジョンドラマアカデミー賞主演女優賞を受賞。現在もドラマや映画、舞台などで活躍中です。' where id = 'H2sV1kM5czz6toPmUSLL0';
update content_bodies set title = 'Nao | Delicious Tokachi Address【Tabiiro Movie】', description = 'The Tokachi area in Hokkaido is known as one of Japan''s leading agricultural and dairy farming regions, boasting a food self-sufficiency rate of approximately 1,100% across its 19 municipalities. This abundance of ingredients leads to a continuous encounter with exquisite gourmet food during travels. Nao, who has a passion for delicious food, explores the towns of Tokachi and enjoys the blessings of the land. Nao, born on February 10, 1995, in Fukuoka Prefecture, gained attention for her role as the heroine''s best friend in the NHK morning drama ''Hanbun, Aoi.'' She has since appeared in various notable works, including ''Anata no Ban desu'' and films like ''Yomei 10-nen'' and ''My Broken Mariko.'' After winning the 2023 Elan d''Or Award for Best Newcomer and the 116th Television Drama Academy Award for Best Actress, she continues to thrive in dramas, films, and theater.' where id = 'Z9DKon0gx2USgbhFrUECX';
update content_bodies set title = '貫地谷しほり｜北海道 美唄の旅物語', description = '美唄市は北海道中西部に位置し、日本有数の炭鉱まちとして知られています。貫地谷しほりさんが美唄を訪れ、自然と調和した炭鉱跡や、世界的に有名な彫刻家の作品が展示される美術館を巡ります。また、かつて炭鉱夫たちを支えたソウルフードや、市を代表する新旧の銘菓にも出会い、ここでしか味わえない風景と食を楽しむ旅が描かれています。' where id = 'FPDsKYdu1m9tQ4pfKzx2C';
update content_bodies set title = 'Shihori Kanjiya | Travel Story in Bibai, Hokkaido', description = 'Bibai City, located in the central-western part of Hokkaido, is known as one of Japan''s prominent coal mining towns. In this travel story, Shihori Kanjiya visits Bibai to explore the harmonious landscapes of former coal mines, a museum featuring the works of a world-renowned sculptor, and the local soul food that once supported coal miners. She also encounters both traditional and modern confections that represent the city, showcasing unique scenery and cuisine that can only be found here.' where id = 'SPAbDO2oe9hCWD6Znlbhl';
update content_bodies set title = '男鹿温泉へ行くなら！秘湯から名湯までおすすめ宿１０選', description = 'この動画は秋田県への旅行を計画している方に向けて、男鹿温泉のおすすめ宿を紹介しています。秘湯から名湯まで、10軒の宿泊施設が取り上げられています。視聴者には、他のおすすめがあればコメント欄でシェアしてほしいと呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見できるようなきっかけを提供したいと考えています。' where id = 'Uakn-K8hv3LVa1k5ynTiy';
update content_bodies set title = 'Recommended Accommodations in Oga Onsen: 10 Hidden Gems and Famous Hot Springs', description = 'This video serves as a guide for those traveling to Akita Prefecture, specifically highlighting Oga Onsen. It features ten recommended accommodations ranging from hidden gems to well-known hot springs. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, lodging, and dining. The team behind the channel believes in enriching lives through travel and hopes to inspire viewers to discover new possibilities and enjoy their journeys.' where id = 't5L0yJ1YYcsMXbCHcWHHE';
