update content_bodies set title = '米倉涼子さんの札幌まち歩き', description = '米倉涼子さんが晩秋の札幌を訪れます。観光名所も魅力的ですが、地元の人々に愛される場所を訪れることを楽しんでいます。知る人ぞ知るアートな公園を散策したり、知り合いのシェフのお店を訪れたりして、日常の延長のように旅を満喫しています。' where id = '_XsX2HAOzNiQur7aW6IUX';
update content_bodies set title = 'Ryo Koike''s Walking Tour in Sapporo | Hokkaido, Sapporo <Tabiiro>', description = 'Ryo Koike visits Sapporo in late autumn. While popular tourist spots are great, she enjoys exploring places loved by locals. The journey includes strolling through lesser-known artistic parks and visiting a friend''s restaurant, making the trip feel like a continuation of her daily life.' where id = '-E-_zBKmFH4v4ERV6E9hz';
