update content_bodies set title = '【神奈川観光】これは外せない！江の島のおすすめ観光スポット', description = '神奈川県への旅行を計画している方に向けて、江の島の必見観光スポットを紹介する動画です。視聴者には、他のおすすめスポットがあればコメントでシェアしてほしいと呼びかけています。このチャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関する情報を提供し、旅行をより楽しくすることを目的としています。江の島の観光名所として、新江ノ島水族館、江島神社、江ノ島シーキャンドルなどが紹介されています。訪れる前には公式サイトで最新情報を確認することを推奨しています。' where id = 'J4DZQE4O9bRyWbyM2Ayio';
update content_bodies set title = 'Must-See Tourist Spots in Enoshima, Kanagawa', description = 'This video serves as a guide for those traveling to Kanagawa, specifically highlighting essential tourist spots in Enoshima. It encourages viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on various aspects of travel, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities through their journeys. The video outlines several key attractions in Enoshima, including the Enoshima Aquarium, Enoshima Shrine, and the Enoshima Sea Candle, among others. Viewers are advised to check official websites for the latest information before visiting.' where id = 'n9rzhQoRZlvka8DreqwE9';
update content_bodies set title = '映画『ふくいけん』予告編【地味にすごい、福井動画コンテスト入賞作品】', description = '本作品は、「地味にすごい、福井」をテーマにした福井県の動画コンテストで入賞した作品です。物語は、古いバーのマスターが福井での思い出を語るところから始まります。カニやメガネ、そしてあの崖も登場し、恐竜に襲われる街の行く末が描かれます。ハリウッド映画の予告編風に、福井の「地味にすごい見どころ」を紹介しています。福井県の観光情報は、福井県観光連盟のウェブサイトでご覧いただけます。' where id = 'OA4JK-OKDqKVsskGyERdD';
update content_bodies set title = 'Trailer for the Movie ''Fukuiden'' - Award-Winning Work from the ''Subtly Amazing Fukui'' Video Contest', description = 'This work is an award-winning entry from a video contest held by Fukui Prefecture, themed ''Subtly Amazing Fukui.'' The story begins with the master of an old bar reminiscing about his memories in Fukui, featuring crabs, glasses, and a notable cliff. The fate of a town ravaged by dinosaurs is also explored. The trailer introduces Fukui''s ''subtly amazing highlights'' in a Hollywood movie trailer style. For more tourism information about Fukui Prefecture, visit the Fukui Prefectural Tourism Federation website.' where id = 'qmISt1fSQ5TG8RBqpqFlX';
update content_bodies set title = '【歌詞付き】大垣城ＰＲアニメーション動画「カモン大垣」', description = 'このプロモーション動画は、呂布カルマのラップにのせて大垣城をPRする内容で、歌詞付きのバージョンです。大垣市は岐阜県に位置し、歴史的な背景を持つ街として知られています。松尾芭蕉の「奥の細道」の結びの地であり、関ヶ原合戦の際には西軍の本拠地となった大垣城が存在します。また、豊富な地下水に恵まれた「水の都」としても知られ、自然と歴史が共存する魅力的な場所です。春には大垣まつりが開催され、多くの観光客で賑わいます。' where id = 'tAYXWTFnL-l183BJuQAsX';
update content_bodies set title = 'Promotional Animation Video for Ogaki Castle: ''Come on Ogaki'' with Lyrics', description = 'This promotional video features a rap by Rofu Karma that promotes Ogaki Castle, presented in a version with lyrics. The video highlights the historical significance of Ogaki City, located in Gifu Prefecture, known for its rich history and cultural heritage. It mentions notable figures like Matsuo Basho and events such as the Battle of Sekigahara, emphasizing the city''s attractions, including Ogaki Castle and the UNESCO-listed Ogaki Festival. The city is celebrated for its abundant underground water and natural beauty, making it a desirable place to live and visit.' where id = 'EXjusxz_zN6hp7jZuhtUf';
update content_bodies set title = '本場静岡のおすすめ！美味しいうなぎが食べられる人気店', description = '静岡県への旅行や観光に役立つ情報を提供する動画です。安価でリーズナブルなお店から有名な人気店まで、ぜひ訪れたい美味しいうなぎ料理店を紹介しています。視聴者には、動画で紹介されていないおすすめの店をコメント欄でシェアするよう呼びかけています。また、旅行の達人チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることを信じており、視聴者に新しい可能性を発見することを促しています。' where id = '0LI1jt3ttHUl7J5F9rABg';
