update content_bodies set title = 'USJを２倍楽しむ！ユニバの豆知識７選', description = 'この動画では、大阪のユニバーサル・スタジオ・ジャパン（USJ）をより楽しむための豆知識を7つ紹介しています。これらの情報は、パークでの体験を向上させるために役立ちます。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。また、旅行の達人の公式LINEアカウントでは、旅行に関するお得な情報を配信しており、旅行をより豊かにすることを目指しています。旅行の達人チャンネルは、観光、宿泊、食事などの情報を提供し、より快適で楽しい旅行をサポートします。' where id = 'VnnUhUMEoY-vSufTEWALd';
