update content_bodies set title = 'コスパのよい人気の水出しアイスコーヒー店', description = '東京への旅行や観光の参考になる動画で、特に「コールドブリューコーヒー」を扱うカフェを紹介しています。関東の中でも多くの店舗がある東京から、おすすめのカフェをピックアップしました。視聴者には、動画で紹介されていないおすすめの店をコメント欄でシェアするよう呼びかけています。このチャンネル「旅行の達人」は、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目的としています。旅行を通じて人生を豊かにすることを信じており、多くの人が新しい可能性を発見するきっかけになればと願っています。' where id = 'Frz8QRB54fapB-j_LrMlj';
