update content_bodies set title = '【愛知観光】名古屋に来たらやりたい15のこと', description = '愛知県への旅行や観光の参考として、名古屋で体験したいアクティビティを15選紹介する動画です。動画に載っていないおすすめがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。運営メンバーは、年間の半分近くを旅しており、視聴者が新しい可能性を発見し、より豊かな人生を送るきっかけを提供したいと考えています。' where id = 'CdmHrB2JF2GvWzKNpaGMr';
