update content_bodies set title = 'Recommended Gyoza Restaurants in Fukushima: Top 10', description = 'This guide is perfect for those traveling to Fukushima Prefecture. Known for its famous round gyoza, Fukushima boasts numerous eateries. Here, we present ten recommended gyoza restaurants, each renowned for their delicious offerings. Be sure to check them out during your visit!' where id = 'fVpmT8_q2gM_HlY3tKpWN';
update content_bodies set title = '三重の観光スポット10選', description = '三重県への旅行を計画している方に最適なガイドです。雨の日の観光は気分が下がることがありますが、天候に関係なく楽しめる観光スポットを知っていれば、気にせず楽しむことができます。この動画では、雨の日でも楽しめる三重県の観光スポットを10カ所紹介しています。動画に紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。また、旅行の達人では、旅行をより楽しくするための情報を提供しており、公式LINEアカウントを通じてお得な旅行情報も配信しています。旅行を通じて新しい可能性を発見し、人生を豊かにすることを目指しています。' where id = 'CXEsRmmWaTT9hFvEA90PC';
update content_bodies set title = 'Top 10 Tourist Spots in Mie Prefecture', description = 'This guide is perfect for those planning a trip to Mie Prefecture. Rainy days can dampen the excitement of sightseeing, but knowing about attractions that can be enjoyed regardless of the weather can make all the difference. This video presents ten tourist spots in Mie that are enjoyable even on rainy days. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel also offers a free LINE account for travel tips and deals, aiming to enhance your travel experience. The channel is dedicated to providing comprehensive travel information, helping viewers discover new possibilities and enrich their lives through travel.' where id = 'YWnIKGYmEyhs1wNLSmfCj';
update content_bodies set title = '群馬 観光】赤城山周辺の観光スポット15選', description = '群馬県に位置する赤城山は、日本百名山の一つで、都心から車で約2時間半でアクセス可能な自然豊かなエリアです。日帰り旅行にも適しており、季節ごとに桜やつつじを楽しむことができ、さまざまな自然アクティビティも体験できます。今回は、赤城山周辺の人気観光スポットを15選紹介します。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。旅行の達人チャンネルは、旅行をより楽しくするための情報を提供しています。' where id = 'ZBuC-41vRp4l3Y3KKGDVq';
update content_bodies set title = '15 Recommended Tourist Spots Around Mount Akagi in Gunma', description = 'Mount Akagi, one of Japan''s 100 famous mountains, is located in Gunma Prefecture and is easily accessible from the city, taking about two and a half hours by car. This popular area is rich in nature and is perfect for day trips, offering seasonal attractions like cherry blossoms and azaleas, as well as various outdoor activities. This video introduces 15 popular tourist spots around Mount Akagi in Gunma Prefecture. If you have any recommendations not mentioned in the video, please share them in the comments. The channel aims to provide enjoyable travel information to enhance your travel experiences.' where id = '87VT2IJGLBIBiaIQDACSm';
update content_bodies set title = '立山黒部｜TATEYAMA WINTER MOVIE　4K', description = 'このプロモーション動画は、立山の冬の魅力をまとめたものです。撮影ロケ地には、雨晴海岸から見える立山連峰（朝日）、呉羽山公園からの立山連峰、立山山麓スキー場、立山博物館が含まれています。富山の観光情報は、こちらからご覧いただけます。http://www.info-toyama.com/' where id = '7uHar6-6ss3nvy2nf7QdL';
update content_bodies set title = 'Tateyama Black Mountain | TATEYAMA WINTER MOVIE 4K', description = 'This promotional video showcases the winter attractions of Tateyama. Filming locations include the Tateyama mountain range visible from the Amanohashidate coast (Asahi), the Tateyama mountain range from Kureha Park, the Tateyama foothills ski resort, and the Tateyama Museum.' where id = 'Tf1LKVqOp7LP0PBdOY1T_';
update content_bodies set title = '東洋一美しいビーチ ～与那覇前浜ビーチ～', description = '宮古島の与那覇前浜ビーチは、様々なランキングで何度も1位を獲得した、宮古島が誇る東洋一美しいビーチです。全長約7キロにわたるきめ細やかで真っ白な砂浜が広がり、時間ごとに変化する宮古ブルーの美しいグラデーションを楽しむことができます。空撮映像でその魅力を堪能してください。また、宮古諸島の美しい景色を集めたパンフレットのデジタル版も公開されましたので、ぜひご覧ください。' where id = 'M5PerOKn0pKJGq_4owA4n';
update content_bodies set title = 'Yonaha Maehama Beach: The Best Beach in the Orient', description = 'Yonaha Maehama Beach, located on Miyako Island, is renowned for being one of the most beautiful beaches in the Orient, having topped various rankings multiple times. The beach features approximately 7 kilometers of fine, white sand and showcases the stunning gradient of Miyako Blue that changes throughout the day. Enjoy aerial footage that captures the beauty of this remarkable location. Additionally, a digital version of a brochure showcasing the beautiful scenery of the Miyako Islands has been released. Be sure to check it out!' where id = 'zQ_k0QzKDkEc5X1SLG84S';
