update content_bodies set title = 'Top 10 Gourmet Delights in Iwate', description = 'Iwate Prefecture is known for its delicious food offerings. This guide introduces ten must-try gourmet dishes that will surely entice visitors. Each restaurant featured is packed with charm, making them worth a visit when you''re in the area. Whether you''re traveling or sightseeing, this list serves as a great reference for enjoying the culinary delights of Iwate.' where id = 'CKJgwjgvxC7PreGgbcN9l';
update content_bodies set title = '【三重 観光】伊勢の人気ランチスポット10選', description = '三重県への旅行や観光に役立つ情報です。食材の宝庫とされる三重県南勢の中でも、伊勢は食材にこだわった老舗が多く、斬新な味の新スポットも続々登場しています。伊勢には、普段は敷居が高い老舗でもランチならお得に楽しめるお店がたくさんあります。地元のグルメや昔ながらのソウルフードを楽しめるお店を含む、伊勢で人気のランチスポットを10選ご紹介します。この動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。' where id = 'dnEpAsSGuUTgW9YxzKWyz';
update content_bodies set title = 'Top 10 Popular Lunch Spots in Ise, Mie', description = 'This guide is perfect for those traveling to Mie Prefecture. Known as a treasure trove of ingredients, the Nansei region of Mie, particularly Ise, boasts many long-established restaurants that focus on quality ingredients, alongside new spots offering innovative flavors. Ise has numerous recommended lunch spots where you can enjoy local gourmet dishes and traditional soul food at reasonable prices, making it easier to try renowned establishments that might usually seem too upscale. This video presents ten popular lunch spots in Ise. If you have any other recommendations not mentioned in the video, feel free to share them in the comments!' where id = 'deXDgD3TmAu9192_1Q2i7';
